// План specs/invoices.md 5.1 (#ffde48). PROD, admin, компания «test», десктоп, EN. Только чтение (@prod-safe).
// Старые дубли номеров в компании «test» исправлены: INV-0023 — один счёт, вторая копия — INV-0055; в списке нет повторяющихся номеров.
// Источник: «מה רצוי» — לכל חשבונית בחברה מספר ייחודי. Факты 17.11: 58 счетов без повторов, INV-0023 один.
// Не сверено с сайтом при записи: поле поиска на /invoices (placeholder «Search…»); пагинация — берутся номера всех загруженных строк.
import { test, expect } from '../../fixtures';
import { PROD_ROLE, expectTestCompany, prepareProdTest } from './invoice-helpers';

test.describe('Invoice numbers are unique in the company (#ffde48)', () => {
  test('Search INV-0023 finds exactly one invoice; INV-0055 exists (the former second copy) #ffde48 @desktop @prod-safe', async ({ asUser }) => {
    const page = await asUser(PROD_ROLE);
    await prepareProdTest(page);
    await page.goto('/invoices');
    await expectTestCompany(page);
    const search = page.getByPlaceholder(/^Search/i).first();
    await expect(search).toBeVisible({ timeout: 30_000 });

    await search.fill('INV-0023');
    const exact = (n: string) => page.getByRole('row').filter({ has: page.getByRole('button', { name: n, exact: true }) });
    await expect(exact('INV-0023'), 'один счёт INV-0023').toHaveCount(1, { timeout: 20_000 });

    await search.fill('INV-0055');
    await expect(exact('INV-0055'), 'вторая копия переименована в INV-0055').toHaveCount(1, { timeout: 20_000 });
  });

  test('No repeated invoice numbers in the whole Invoices list #ffde48 @desktop @prod-safe', async ({ asUser }) => {
    const page = await asUser(PROD_ROLE);
    await prepareProdTest(page);
    await page.goto('/invoices');
    await expectTestCompany(page);
    const numbers = page.getByRole('button', { name: /^INV-\d+$/ });
    await expect(numbers.first()).toBeVisible({ timeout: 30_000 });
    // Догружаем список прокруткой, пока число строк растёт
    let prev = -1;
    for (let i = 0; i < 10; i++) {
      const n = await numbers.count();
      if (n === prev) break;
      prev = n;
      await page.mouse.wheel(0, 4000);
      await expect.poll(() => numbers.count(), { timeout: 3_000 }).toBeGreaterThanOrEqual(n).catch(() => undefined);
    }
    const all = (await numbers.allInnerTexts()).map((t) => t.trim());
    const dupes = all.filter((n, i) => all.indexOf(n) !== i);
    expect(dupes, `повторяющиеся номера счетов среди ${all.length}`).toEqual([]);
  });
});
